function hapusDiIndex(arr, i) {
  return [...arr.slice(0, i), ...arr.slice(i + 1)];
}
const asli = ["Kopi", "Teh", "Roti", "Susu"];
const baru = hapusDiIndex(asli, 1);
console.log(baru.join(", "));
console.log(asli.join(", "));
console.log(hapusDiIndex(asli, 3).join(", "));
